-- Pilot RPC qualification, all synthetic rows rolled back; no real Auth session.
BEGIN ISOLATION LEVEL REPEATABLE READ;
SET LOCAL statement_timeout='20s'; SET LOCAL lock_timeout='2s';
DO $identity$ DECLARE actor uuid; est uuid; BEGIN
 SELECT owner_id,establishment_id INTO STRICT actor,est FROM private.pilot_owner_config WHERE singleton AND activation_complete;
 IF actor IS NULL OR est IS NULL THEN RAISE EXCEPTION 'OWNER_NOT_QUALIFIED'; END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 PERFORM set_config('stopflow.test_est',est::text,true);
END $identity$;
SET LOCAL ROLE authenticated;
DO $qualification$
DECLARE est uuid:=current_setting('stopflow.test_est')::uuid; room uuid; layout uuid; rv bigint; lv bigint; payload jsonb:='[]'; marks jsonb:='[]'; item jsonb; t jsonb; el public.reservation_layout_elements; reference jsonb:='{"tables": [{"reference_label": "4", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 38.0, "y": 93.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "5", "shape": "rectangle", "capacity_proposed": 4, "capacity_requires_validation": true, "x": 169.0, "y": 35.0, "width": 54, "height": 88, "rotation": 0}, {"reference_label": "6", "shape": "rectangle", "capacity_proposed": 4, "capacity_requires_validation": true, "x": 298.0, "y": 35.0, "width": 54, "height": 88, "rotation": 0}, {"reference_label": "7", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 243.0, "y": 164.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "8", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 243.0, "y": 256.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "9", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 243.0, "y": 347.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "3", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 40.0, "y": 273.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "2", "shape": "rectangle", "capacity_proposed": 4, "capacity_requires_validation": true, "x": 41.0, "y": 439.0, "width": 88, "height": 54, "rotation": 0}, {"reference_label": "10", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 243.0, "y": 439.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "1", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 243.0, "y": 550.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "26", "shape": "rectangle", "capacity_proposed": 4, "capacity_requires_validation": true, "x": 796.0, "y": 35.0, "width": 54, "height": 88, "rotation": 0}, {"reference_label": "25", "shape": "rectangle", "capacity_proposed": 4, "capacity_requires_validation": true, "x": 999.0, "y": 35.0, "width": 54, "height": 88, "rotation": 0}, {"reference_label": "24", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 999.0, "y": 145.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "23", "shape": "rectangle", "capacity_proposed": 4, "capacity_requires_validation": true, "x": 999.0, "y": 221.0, "width": 54, "height": 88, "rotation": 0}, {"reference_label": "22", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 999.0, "y": 329.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "21", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 999.0, "y": 421.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "20", "shape": "rectangle", "capacity_proposed": 4, "capacity_requires_validation": true, "x": 999.0, "y": 514.0, "width": 54, "height": 88, "rotation": 0}, {"reference_label": "31", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 758.0, "y": 199.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "32", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 869.0, "y": 199.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "30", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 758.0, "y": 309.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "33", "shape": "square", "capacity_proposed": 2, "capacity_requires_validation": true, "x": 869.0, "y": 309.0, "width": 54, "height": 54, "rotation": 0}, {"reference_label": "S1 A", "shape": "round", "capacity_proposed": 30, "capacity_requires_validation": true, "x": 449.0, "y": 167.0, "width": 158, "height": 158, "rotation": 0}, {"reference_label": "S1 B", "shape": "round", "capacity_proposed": 10, "capacity_requires_validation": true, "x": 449.0, "y": 356.0, "width": 158, "height": 158, "rotation": 0}, {"reference_label": "SA1", "shape": "rectangle", "capacity_proposed": 8, "capacity_requires_validation": true, "x": 685.0, "y": 440.0, "width": 164, "height": 54, "rotation": 0}, {"reference_label": "SA2", "shape": "rectangle", "capacity_proposed": 8, "capacity_requires_validation": true, "x": 685.0, "y": 531.0, "width": 164, "height": 54, "rotation": 0}], "decor": [{"label": "Emp1 · À emporter", "kind": "label", "usage": "repere_a_emporter_sans_table_reservable", "x": 428, "y": 53, "width": 54, "height": 54, "rotation": 0}, {"label": "Emp2 · À emporter", "kind": "label", "usage": "repere_a_emporter_sans_table_reservable", "x": 501, "y": 53, "width": 54, "height": 54, "rotation": 0}, {"label": "Emp3 · À emporter", "kind": "label", "usage": "repere_a_emporter_sans_table_reservable", "x": 575, "y": 53, "width": 54, "height": 54, "rotation": 0}]}'::jsonb; before_hash text; after_hash text; result jsonb; refused boolean;
BEGIN
 SELECT md5(jsonb_agg(to_jsonb(x) ORDER BY id)::text) INTO before_hash FROM public.reservation_tables x;
 result:=public.reservations_save_room(est,NULL,NULL,'Fixture plan qualification '||gen_random_uuid(),'SYNTHETIC_ROLLBACK',0,true);room:=(result->>'id')::uuid;
 SELECT id,version INTO STRICT layout,lv FROM public.reservation_layouts WHERE room_id=room AND width=1100 AND height=660;
 FOR item IN SELECT value FROM jsonb_array_elements(reference->'tables') LOOP
  t:=public.reservations_save_table(est,room,NULL,NULL,item->>'reference_label',(item->>'capacity_proposed')::int,item->>'shape',true);
  SELECT * INTO STRICT el FROM public.reservation_layout_elements WHERE table_id=(t->>'id')::uuid;
  payload:=payload||jsonb_build_array(jsonb_build_object('element_id',el.id,'table_id',el.table_id,'expected_version',el.version,'x',(item->>'x')::numeric,'y',(item->>'y')::numeric,'width',(item->>'width')::numeric,'height',(item->>'height')::numeric,'rotation',(item->>'rotation')::numeric));
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(reference->'decor') LOOP
  marks:=marks||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'kind','label','x',(item->>'x')::numeric,'y',(item->>'y')::numeric,'width',(item->>'width')::numeric,'height',(item->>'height')::numeric,'rotation',0,'properties',jsonb_build_object('label',item->>'label')));
 END LOOP;
 SELECT version INTO STRICT lv FROM public.reservation_layouts WHERE id=layout;
 PERFORM public.reservations_service_plan_save(est,room,layout,lv,payload,marks);
 IF (SELECT count(*) FROM public.reservation_tables WHERE room_id=room)<>25 OR (SELECT count(*) FROM public.reservation_layout_elements WHERE room_id=room AND table_id IS NULL)<>3 THEN RAISE EXCEPTION 'REFERENCE_COUNTS'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(payload) LOOP
 SELECT * INTO STRICT el FROM public.reservation_layout_elements WHERE id=(item->>'element_id')::uuid;
 IF el.x<>(item->>'x')::numeric OR el.y<>(item->>'y')::numeric OR el.width<>(item->>'width')::numeric OR el.height<>(item->>'height')::numeric THEN RAISE EXCEPTION 'REFERENCE_COORDINATES'; END IF;
 END LOOP;
 refused:=false;BEGIN PERFORM public.reservations_service_plan_save(est,room,layout,lv,payload,marks); EXCEPTION WHEN serialization_failure THEN refused:=true;END;
 IF NOT refused THEN RAISE EXCEPTION 'VERSION_GUARD_MISSING'; END IF;
 SELECT version INTO rv FROM public.reservation_rooms WHERE id=room;
 PERFORM public.reservations_save_room(est,room,rv,'Fixture plan archivé','SYNTHETIC_ROLLBACK',0,false);
 IF (SELECT active FROM public.reservation_rooms WHERE id=room) THEN RAISE EXCEPTION 'ARCHIVE_NOT_CONFIRMED'; END IF;
 SELECT version INTO rv FROM public.reservation_rooms WHERE id=room;
 PERFORM public.reservations_save_room(est,room,rv,'Fixture plan restauré','SYNTHETIC_ROLLBACK',0,true);
 SELECT md5(jsonb_agg(to_jsonb(x) ORDER BY id)::text) INTO after_hash FROM public.reservation_tables x WHERE room_id<>room;
 IF before_hash IS DISTINCT FROM after_hash THEN RAISE EXCEPTION 'ORIGINAL_TABLES_CHANGED'; END IF;
 PERFORM set_config('stopflow.test_result',jsonb_build_object('resultat','PASS','type','RPC_SQL_PILOTE_AUTH_SIMULEE_TRANSACTION_ROLLBACK','tables',25,'reperes',3,'coordonnees_conformes',true,'conflit_version_refuse',true,'archivage_reversible',true,'tables_preexistantes_inchangees',true)::text,true);
END $qualification$;
SELECT current_setting('stopflow.test_result')::jsonb AS qualification;
ROLLBACK;
